    "content": "Контекстные действия Admin & CRUD Контекстные действия admin-crud/context-menu.html Контекстные действия Виды действий Примеры Control::view() Control::manage() Control::copy() Control::localizedCopy() Control::print() Control::enabled() Control::separator() Control::runAndReload() Control::source() Control::item() Control::modal() Control::html() protected function getControls(): array { return [ Control::view(), Control::manage(), Control::copy(), Control::enabled(), ]; } protected function getControls(): array { return [ Control::view(), Control::manage(), Control::separator(), Control::runAndReload( ['action' => 'confirmPayment'], \\Air\\Type\\FaIcon::ICON_CHECK, 'Confirm payment', 'Confirm this payment?' ), ]; } public function confirmPayment(\\App\\Model\\Order $order): void { $order->status = \\App\\Model\\Order::STATUS_PAID; $order->save(); \\App\\Service\\Notification::paymentConfirmed($order); } protected function getControls(): array { return [ Control::view(), Control::source(function (\\App\\Model\\User $user) { return Control::item( ['controller' => 'order', 'action' => 'index', 'params' => ['user' => $user->id]], \\Air\\Type\\FaIcon::ICON_BRIEFCASE, 'Orders' ); }), ]; } AirCMS Docs / Admin & CRUD / Контекстные действия Контекстные действия Контекстные действия относятся к одной записи таблицы: view, manage, copy, enable/disable, custom action, modal. Виды действий Метод Что делает Control::view() Просмотр записи. Control::manage() Редактирование. Control::copy() Копирование. Control::localizedCopy() Копия для другого языка. Control::print() Печать. Control::enabled() Enable/disable. Control::separator() Разделитель. Control::runAndReload() Запуск action и reload. Control::source() Кастомный пункт. Control::item() Ссылка. Control::modal() iframe-modal. Control::html() htmlAjax-modal. Примеры Базовый набор protected function getControls(): array { return [ Control::view(), Control::manage(), Control::copy(), Control::enabled(), ]; } Подтвердить оплату protected function getControls(): array { return [ Control::view(), Control::manage(), Control::separator(), Control::runAndReload( ['action' => 'confirmPayment'], \\Air\\Type\\FaIcon::ICON_CHECK, 'Confirm payment', 'Confirm this payment?' ), ]; } public function confirmPayment(\\App\\Model\\Order $order): void { $order->status = \\App\\Model\\Order::STATUS_PAID; $order->save(); \\App\\Service\\Notification::paymentConfirmed($order); } Пункт Orders для пользователя protected function getControls(): array { return [ Control::view(), Control::source(function (\\App\\Model\\User $user) { return Control::item( ['controller' => 'order', 'action' => 'index', 'params' => ['user' => $user->id]], \\Air\\Type\\FaIcon::ICON_BRIEFCASE, 'Orders' ); }), ]; } AirCMS - aircms.pro"
