    "content": "Свои страницы и кастомные формы Admin & CRUD Свои страницы admin-crud/custom-pages.html Свои страницы и кастомные формы Своя страница Кастомная форма не через manage() Страница деталей public function import(): void { $this->getView()->setVars([ 'title' => 'Import products', 'form' => new \\App\\Form\\Admin\\ProductImportForm(), ]); $this->getView()->setScript('product/import'); } <h1><?php echo $this->title; ?></h1> <?php echo $this->form->render(); ?> <?php namespace App\\Form\\Admin; use Air\\Form\\Form; use Air\\Form\\Input; class ProductImportForm extends Form { public function __construct() { parent::__construct(elements: [ Input::storage('file'), Input::checkbox('dryRun'), ]); } } public function import(): array|void { $form = new \\App\\Form\\Admin\\ProductImportForm(); if ($this->getRequest()->isPost()) { if (!$form->isValid($this->getRequest()->getPostAll())) { $this->getResponse()->setStatusCode(400); return [ 'errors' => $form->getErrorFields(), ]; } $result = \\App\\Service\\ProductImport::run($form->getCleanValues()); return [ 'imported' => $result->imported, 'skipped' => $result->skipped, ]; } $this->getView()->setVars(['form' => $form]); $this->getView()->setScript('product/import'); } public function details(\\App\\Model\\Order $order): void { $this->getView()->setVars([ 'order' => $order, 'items' => $order->items, 'history' => \\App\\Model\\OrderHistory::fetchAll(['order' => $order]), ]); $this->getView()->setScript('order/details'); } AirCMS Docs / Admin & CRUD / Свои страницы Свои страницы и кастомные формы Admin controller может содержать свои actions: import, preview, confirm, details, report, settings. Своя страница Action import() public function import(): void { $this->getView()->setVars([ 'title' => 'Import products', 'form' => new \\App\\Form\\Admin\\ProductImportForm(), ]); $this->getView()->setScript('product/import'); } View script <h1><?php echo $this->title; ?></h1> <?php echo $this->form->render(); ?> Кастомная форма не через manage() ProductImportForm <?php namespace App\\Form\\Admin; use Air\\Form\\Form; use Air\\Form\\Input; class ProductImportForm extends Form { public function __construct() { parent::__construct(elements: [ Input::storage('file'), Input::checkbox('dryRun'), ]); } } Обработка формы public function import(): array|void { $form = new \\App\\Form\\Admin\\ProductImportForm(); if ($this->getRequest()->isPost()) { if (!$form->isValid($this->getRequest()->getPostAll())) { $this->getResponse()->setStatusCode(400); return [ 'errors' => $form->getErrorFields(), ]; } $result = \\App\\Service\\ProductImport::run($form->getCleanValues()); return [ 'imported' => $result->imported, 'skipped' => $result->skipped, ]; } $this->getView()->setVars(['form' => $form]); $this->getView()->setScript('product/import'); } Страница деталей details action public function details(\\App\\Model\\Order $order): void { $this->getView()->setVars([ 'order' => $order, 'items' => $order->items, 'history' => \\App\\Model\\OrderHistory::fetchAll(['order' => $order]), ]); $this->getView()->setScript('order/details'); } AirCMS - aircms.pro"
