    "url": "localization/admin-ui.html",
    "content": "Локализация в админке Localization Админка localization/admin-ui.html Локализация в админке Подключение разделов CRUD-модель с языком <?php use Air\\Config; use Air\\Crud\\Nav\\Nav; return Config::defaults( project: 'AIR', admin: fn() => Config::admin( domain: 'admin.*', title: 'AirCMS', settings: [ [ Nav::SETTINGS_LANGUAGES, Nav::SETTINGS_PHRASES ] ] ) ); <?php namespace App\\Module\\Admin\\Controller; use Air\\Crud\\Controller\\Many; use Air\\Crud\\Controller\\ManyHelper\\Accessor\\Filter; use Air\\Crud\\Controller\\ManyHelper\\Accessor\\Header; use Air\\Form\\Form; use Air\\Form\\Input; class Article extends Many { protected function getHeader(): array { return [ Header::text(by: 'title'), Header::language(), Header::enabled(), Header::createdAndUpdated() ]; } protected function getFilter(): array { return [ Filter::search(['title', 'url']), Filter::language(), Filter::enabled() ]; } protected function getForm($model = null): Form { return new Form(elements: [ Input::text('title'), Input::text('url'), Input::model('language', model: \\Air\\Crud\\Model\\Language::class), Input::checkbox('enabled') ]); } } AirCMS Docs / Localization / Админка Admin UI Languages Phrases Локализация в админке Админка может управлять списком языков, фразами и контентными записями, связанными с конкретным языком. Подключение разделов <?php use Air\\Config; use Air\\Crud\\Nav\\Nav; return Config::defaults( project: 'AIR', admin: fn() => Config::admin( domain: 'admin.*', title: 'AirCMS', settings: [ [ Nav::SETTINGS_LANGUAGES, Nav::SETTINGS_PHRASES ] ] ) ); CRUD-модель с языком <?php namespace App\\Module\\Admin\\Controller; use Air\\Crud\\Controller\\Many; use Air\\Crud\\Controller\\ManyHelper\\Accessor\\Filter; use Air\\Crud\\Controller\\ManyHelper\\Accessor\\Header; use Air\\Form\\Form; use Air\\Form\\Input; class Article extends Many { protected function getHeader(): array { return [ Header::text(by: 'title'), Header::language(), Header::enabled(), Header::createdAndUpdated() ]; } protected function getFilter(): array { return [ Filter::search(['title', 'url']), Filter::language(), Filter::enabled() ]; } protected function getForm($model = null): Form { return new Form(elements: [ Input::text('title'), Input::text('url'), Input::model('language', model: \\Air\\Crud\\Model\\Language::class), Input::checkbox('enabled') ]); } } AirCMS - aircms.pro"
