    "content": "API-примеры Localization API-примеры localization/api-examples.html API-примеры Base controller Контент текущего языка Сообщения API Phrase::t() <?php namespace App\\Module\\Api\\Controller; use Air\\Core\\Controller; use Air\\Crud\\Model\\Language; abstract class Base extends Controller { protected ?Language $language = null; public function init(): void { parent::init(); $this->getView()->setLayoutEnabled(false); $this->getView()->setAutoRender(false); $this->getResponse()->setHeader('Content-Type', 'application/json'); $languageKey = $this->getRequest()->getHeader('language') ?: 'en'; $this->language = Language::getLanguageWithKey($languageKey); Language::setDefaultLanguage($this->language); } } <?php namespace App\\Module\\Api\\Controller; use App\\Model\\Product; use Air\\Map; class Catalog extends Base { public function products(): array { return Map::execute(Product::all(), [ 'id', 'url', 'title', 'description' ]); } public function details(string $url): array { return Map::execute(Product::one([ 'url' => $url ]), [ 'id', 'url', 'title', 'description' ]); } } <?php use Air\\Crud\\Model\\Phrase; return [ 'success' => true, 'message' => Phrase::t('Profile was updated') ]; AirCMS Docs / Localization / API-примеры API language header Phrase::t() API-примеры В API язык обычно читается из header, устанавливается в базовом контроллере, а дальше используется ORM и Phrase::t() . Base controller <?php namespace App\\Module\\Api\\Controller; use Air\\Core\\Controller; use Air\\Crud\\Model\\Language; abstract class Base extends Controller { protected ?Language $language = null; public function init(): void { parent::init(); $this->getView()->setLayoutEnabled(false); $this->getView()->setAutoRender(false); $this->getResponse()->setHeader('Content-Type', 'application/json'); $languageKey = $this->getRequest()->getHeader('language') ?: 'en'; $this->language = Language::getLanguageWithKey($languageKey); Language::setDefaultLanguage($this->language); } } Контент текущего языка <?php namespace App\\Module\\Api\\Controller; use App\\Model\\Product; use Air\\Map; class Catalog extends Base { public function products(): array { return Map::execute(Product::all(), [ 'id', 'url', 'title', 'description' ]); } public function details(string $url): array { return Map::execute(Product::one([ 'url' => $url ]), [ 'id', 'url', 'title', 'description' ]); } } Сообщения API <?php use Air\\Crud\\Model\\Phrase; return [ 'success' => true, 'message' => Phrase::t('Profile was updated') ]; AirCMS - aircms.pro"
