    "content": "Sitemap Utilities Sitemap utilities/sitemap.html Sitemap Базовый sitemap Методы setHost Host normalizeUrl Normalize addLoc Добавить страницы из моделей addUrl Route helper usage getUrls Debug render Render Image sitemap addUrl Images Air\\Sitemap Air\\SitemapImage <?php use Air\\Sitemap; $sitemap = new Sitemap(); $sitemap ->setHost('https://example.com') ->addLoc('/', time(), '1.00') ->addLoc('/catalog', time(), '0.80'); $this->getResponse()->setHeader('content-type', 'application/xml'); return $sitemap->render(); setHost public function setHost(string $host): static <?php $sitemap->setHost('https://example.com'); normalizeUrl public static function normalizeUrl(string $url): string <?php $url = Sitemap::normalizeUrl('https://example.com//catalog///item'); addLoc public function addLoc(string $loc, int $lastMod, string $priority = \"0.80\"): static <?php foreach (Article::all() as $article) { $sitemap->addLoc( '/article/' . $article->url, $article->updatedAt ?: time(), '0.80' ); } addUrl public function addUrl(array $route, array $params, int $lastMod, string $priority = \"0.80\"): static <?php $sitemap->addUrl( ['controller' => 'article', 'action' => 'details'], ['article' => $article->url], $article->updatedAt ?: time() ); getUrls public function getUrls(): array <?php $urls = $sitemap->getUrls(); render public function render(): string <?php return $sitemap->render(); addUrl public function addUrl(string $route, array $files = []): static <?php $imageSitemap = new SitemapImage(); $imageSitemap->addUrl('/article/' . $article->url, [ $article->image, ...($article->gallery ?? []), ]); return $imageSitemap->render(); AirCMS Docs / Utilities / Sitemap Sitemap Air\\Sitemap генерирует XML sitemap. Air\\SitemapImage генерирует image sitemap. Базовый sitemap <?php use Air\\Sitemap; $sitemap = new Sitemap(); $sitemap ->setHost('https://example.com') ->addLoc('/', time(), '1.00') ->addLoc('/catalog', time(), '0.80'); $this->getResponse()->setHeader('content-type', 'application/xml'); return $sitemap->render(); Методы setHost Задаёт базовый host для sitemap. Сигнатура public function setHost(string $host): static Host <?php $sitemap->setHost('https://example.com'); normalizeUrl Нормализует URL для sitemap. Сигнатура public static function normalizeUrl(string $url): string Normalize <?php $url = Sitemap::normalizeUrl('https://example.com//catalog///item'); addLoc Добавляет URL в sitemap. Это самый простой и рабочий способ. Сигнатура public function addLoc(string $loc, int $lastMod, string $priority = \"0.80\"): static Добавить страницы из моделей <?php foreach (Article::all() as $article) { $sitemap->addLoc( '/article/' . $article->url, $article->updatedAt ?: time(), '0.80' ); } addUrl Добавляет URL через project-level route helper. Используй только если в проекте есть helper для сборки URL из route-array. Сигнатура public function addUrl(array $route, array $params, int $lastMod, string $priority = \"0.80\"): static Route helper usage <?php $sitemap->addUrl( ['controller' => 'article', 'action' => 'details'], ['article' => $article->url], $article->updatedAt ?: time() ); getUrls Возвращает накопленные URL-ы. Сигнатура public function getUrls(): array Debug <?php $urls = $sitemap->getUrls(); render Возвращает XML sitemap строкой. Сигнатура public function render(): string Render <?php return $sitemap->render(); Image sitemap addUrl Добавляет страницу и изображения в image sitemap. Сигнатура public function addUrl(string $route, array $files = []): static Images <?php $imageSitemap = new SitemapImage(); $imageSitemap->addUrl('/article/' . $article->url, [ $article->image, ...($article->gallery ?? []), ]); return $imageSitemap->render(); AirCMS - aircms.pro"
